<script setup lang="ts">
import { computed,onMounted,onUnmounted,reactive,ref,watch,nextTick } from 'vue';
import { invoke } from '@tauri-apps/api/core';
import { getCurrentWindow } from '@tauri-apps/api/window';
import { listen,type UnlistenFn } from '@tauri-apps/api/event';
import { Monitor,Server,Terminal,Plus,ArrowRight,FolderOpen,MoreHorizontal,FileText,Power,LoaderCircle,X,PlugZap } from '@lucide/vue';
import {profilePayload,type Profile} from './connections';
import Fish from './workbench/Fish.vue';
type Snapshot={profiles:Profile[];defaultHome:string;logs:string;active:string|null;version:string;notice:string|null};
const state=ref<Snapshot>({profiles:[],defaultHome:'',logs:'',active:null,version:'0.2.0',notice:null});
const form=reactive<Profile>({id:'',name:'本机管理',kind:'local',home:'',url:'',target:'',remotePort:18080});
const busy=ref(false),status=ref(''),error=ref(false),menu=ref(''),dialog=ref('');
const active=computed(()=>state.value.profiles.find(p=>p.id===state.value.active));
const selected=ref('');const listeners:UnlistenFn[]=[];
const modes=[{id:'local',label:'本机管理',icon:Monitor},{id:'remote',label:'管理地址',icon:Server},{id:'ssh',label:'SSH 连接',icon:Terminal}];
const descriptions={local:'在这台电脑上整理整合包、检查改动和发布版本。',remote:'连接已经运行的管理端，继续维护服务器上的项目。',ssh:'沿用系统 OpenSSH 配置，通过安全转发连接远程管理端。'};
function message(text:string,failed=false){status.value=text;error.value=failed;}
async function attempt(work:()=>Promise<unknown>){try{await work();}catch(e){message(String(e),true);}}
async function refresh(){state.value=await invoke<Snapshot>('load_desktop');if(state.value.notice)message(state.value.notice,true);}
function newProfile(kind:'local'|'remote'|'ssh'='local'){selected.value='';Object.assign(form,{id:'',name:kind==='local'?'本机管理':'我的服务器',kind,home:state.value.defaultHome,url:'',target:'',remotePort:18080});menu.value='';message('');}
function edit(profile:Profile){selected.value=profile.id;Object.assign(form,{home:'',url:'',target:'',remotePort:18080,...profile});menu.value='';message('');}
async function connect(profile:Profile){if(busy.value)return;busy.value=true;message(profile.kind==='local'?'正在启动本机管理端…':profile.kind==='ssh'?'正在建立 SSH 连接…':'正在连接管理端…');try{const saved=await invoke<Profile>('save_profile',{profile:profilePayload(profile)});await invoke('connect_profile',{id:saved.id});selected.value=saved.id;form.id=saved.id;await refresh();message('工作区已打开');}catch(e){message(String(e),true);}finally{busy.value=false;}}
async function remove(profile:Profile){busy.value=true;try{await invoke('delete_profile',{id:profile.id});if(selected.value===profile.id)newProfile();await refresh();message('已移除连接记录');}catch(e){message(String(e),true);}finally{busy.value=false;menu.value='';}}
async function chooseHome(){const path=await invoke<string|null>('choose_home');if(path)form.home=path;}
async function disconnect(){busy.value=true;try{await invoke(dialog.value==='quit'?'quit_application':'disconnect_workspace');await refresh();message('工作区已断开');}catch(e){message(String(e),true);}finally{dialog.value='';busy.value=false;}}
async function quit(){if(active.value)dialog.value='quit';else await invoke('quit_application');}
watch(dialog,value=>{if(value)void nextTick(()=>document.querySelector<HTMLButtonElement>('.native-dialog footer button')?.focus());});
function key(event:KeyboardEvent){if(!dialog.value)return;if(event.key==='Escape'&&!busy.value)dialog.value='';if(event.key==='Tab'){const buttons=[...document.querySelectorAll<HTMLButtonElement>('.native-dialog button:not(:disabled)')];if(event.shiftKey&&document.activeElement===buttons[0]){event.preventDefault();buttons.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===buttons.at(-1)){event.preventDefault();buttons[0]?.focus();}}}
onMounted(()=>{window.addEventListener('keydown',key);document.documentElement.dataset.theme=localStorage.getItem('dfs-desktop-theme')||'light';void attempt(async()=>{await refresh();newProfile();listeners.push(await getCurrentWindow().onFocusChanged(e=>{if(e.payload&&!busy.value)void attempt(refresh);}));listeners.push(await listen('workspace-ended',()=>void attempt(refresh)));});});
onUnmounted(()=>{listeners.forEach(remove=>remove());window.removeEventListener('keydown',key);});
</script>
<template><main class="connection-library"><aside class="connection-sidebar"><header><span>管理连接</span><button class="icon-button" aria-label="新建连接" :disabled="busy" @click="newProfile()"><Plus :size="17"/></button></header><p class="connection-sidebar-note">选择本机或远程工作区</p><div class="saved-list"><article v-for="profile in state.profiles" :key="profile.id" :class="{selected:selected===profile.id}"><button class="connection-pick" :disabled="busy" @click="edit(profile)"><component :is="profile.kind==='local'?Monitor:profile.kind==='ssh'?Terminal:Server" :size="19"/><div><strong>{{profile.name}}</strong><small>{{profile.kind==='local'?'本机管理':profile.kind==='ssh'?profile.target:'远程管理端'}}</small></div><span v-if="profile.id===state.active" class="small-dot"/></button><button class="icon-button" :aria-label="`编辑连接 ${profile.name}`" :disabled="busy" @click="menu=menu===profile.id?'':profile.id"><MoreHorizontal :size="16"/></button><div v-if="menu===profile.id" class="connection-menu"><button :disabled="busy" @click="edit(profile)">编辑连接</button><button :disabled="busy||profile.id===state.active" @click="attempt(()=>remove(profile))">移除连接记录</button></div></article><div v-if="!state.profiles.length" class="connection-empty"><Monitor :size="26"/><span>还没有连接</span><small>从右侧打开第一个管理端</small></div></div><footer><button :disabled="busy" @click="attempt(()=>invoke('open_logs'))"><FileText :size="14"/>运行日志</button><button :disabled="busy" @click="attempt(quit)"><Power :size="14"/>退出桌面端</button><span>桌面版 {{state.version}}</span></footer></aside>
 <section class="connection-editor"><header class="connection-editor-header"><span>工作区</span><span class="subtle">{{selected?'编辑连接':'新建连接'}}</span></header><div class="connection-editor-scroll"><div v-if="active" class="running-connection"><span class="small-dot"/><div><strong>{{active.name}}</strong><small>工作区正在运行</small></div><button class="accent small" :disabled="busy" @click="attempt(()=>invoke('show_workspace'))">返回工作区 <ArrowRight :size="14"/></button><button class="icon-button" title="断开工作区" aria-label="断开工作区" :disabled="busy" @click="dialog='disconnect'"><X :size="16"/></button></div>
  <div class="connection-form-heading"><span class="overline"><Fish :size="15"/>DREAMINGFISH WORKSPACE</span><h1>{{selected?form.name:'从一个连接开始'}}</h1><p>{{selected?'修改连接信息，或打开这个工作区。':'本机的整合包、服务器上的项目，都在同一个桌面里维护。'}}</p></div><nav class="connection-tabs" aria-label="连接方式"><button v-for="item in modes" :key="item.id" :disabled="busy" :class="{active:form.kind===item.id}" @click="form.kind=item.id as Profile['kind'];message('')"><component :is="item.icon" :size="15"/>{{item.label}}</button></nav>
  <form class="connection-form" @submit.prevent="connect(form)"><p class="connection-description">{{descriptions[form.kind]}}</p><label>连接名称<input v-model="form.name" maxlength="60" required :disabled="busy" autocomplete="off"></label><template v-if="form.kind==='local'"><label>管理数据目录<div class="field-with-button"><input v-model="form.home" required :disabled="busy" autocomplete="off"><button type="button" title="选择目录" aria-label="选择管理数据目录" :disabled="busy" @click="attempt(chooseHome)"><FolderOpen :size="16"/></button></div><small>已有管理端目录中的项目和发布记录可以继续使用。</small></label></template><template v-else-if="form.kind==='remote'"><label>管理端地址<input v-model="form.url" type="url" placeholder="https://admin.example.com/" required :disabled="busy" autocomplete="off"><small>也可以使用已有的本机转发地址。</small></label></template><template v-else><label>SSH 配置名称或 user@host<input v-model="form.target" placeholder="例如 my-server" required :disabled="busy" autocomplete="off"></label><label>远程管理端口<input v-model.number="form.remotePort" type="number" min="1" max="65535" required :disabled="busy"></label><small class="ssh-note">使用系统 OpenSSH 的配置、密钥与已知主机记录。</small></template><div class="connection-form-actions"><button class="accent" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="15"/><ArrowRight v-else :size="16"/>{{busy?'正在连接…':form.kind==='local'?'打开工作区':'连接工作区'}}</button><button v-if="busy" type="button" @click="attempt(()=>invoke('cancel_connect'))">取消连接</button><span v-if="selected&&!busy">信息将在连接时保存</span></div><p v-if="status" class="connection-status" :class="{error}" role="status" aria-live="polite">{{status}}</p></form>
  <div class="connection-bottom-note"><PlugZap :size="17"/><span>关闭窗口会收到托盘，工作区可以随时回来。</span></div>
 </div></section><div v-if="dialog" class="modal-backdrop" @click.self="!busy&&(dialog='')"><section class="native-dialog" role="dialog" aria-modal="true"><header><h2>{{dialog==='quit'?'退出桌面端？':'断开当前工作区？'}}</h2></header><p>本机管理会停止所属服务；远程连接会断开，服务器继续运行。</p><footer><button :disabled="busy" @click="dialog=''">取消</button><button class="accent" :disabled="busy" @click="attempt(disconnect)">{{dialog==='quit'?'退出桌面端':'确认断开'}}</button></footer></section></div></main></template>
